function readDrawingForm(base){const o=clone(base),s=drawingStyle(o);s.color=$('#dscolor').value;s.width=+$('#dswidth').value;s.dash=$('#dsdash').value;if($('#dsopacity'))s.opacity=+$('#dsopacity').value/100;if($('#dsfillcolor'))s.fillColor=$('#dsfillcolor').value;if($('#dsborder'))s.border=$('#dsborder').checked;if($('#dsstartending')){s.startEnding=$('#dsstartending').value;s.endEnding=$('#dsendending').value;}if($('#dsfill'))s.fill=+$('#dsfill').value;if($('#dsextleft'))s.extendLeft=$('#dsextleft').checked;if($('#dsextright'))s.extendRight=$('#dsextright').checked;if($('#dsmidline'))s.middleLine=$('#dsmidline').checked;if($('#dsmidcolor')){s.middleColor=$('#dsmidcolor').value;s.middleWidth=+$('#dsmidwidth').value;s.middleDash=$('#dsmiddash').value;}if($('#dslabel')){s.label=$('#dslabel').value;s.labelPosition=$('#dslabelposition').value;s.labelColor=$('#dslabelcolor').value;const font=+$('#dscaptionfont').value;if(!(font>=8&&font<=24))throw Error('Font size must be 8–24.');s.labelSize=font;s.labelBold=$('#dscaptionbold').checked;s.labelItalic=$('#dscaptionitalic').checked;s.labelVertical=$('#dslabelvertical').value}if($('#dsmiddlepoint')){s.middlePoint=$('#dsmiddlepoint').checked;s.priceLabels=$('#dspricelabels').checked;s.stats=$('#dsstats').checked}if($('#dslabelfont')){const size=+$('#dslabelfont').value;if(!(size>=8&&size<=40))throw Error('Label font size must be 8–40.');s.labelSize=size}o.style=s;o.locked=$('#dslocked').checked;o.visibility=DRAWING_FRAMES.filter(f=>$('#dsframe'+f).checked);if(o.type==='text'){const font=+$('#dsfontsize').value;if(!(font>=8&&font<=48))throw Error('Font size must be 8–48.');o.text=$('#dstext').value;o.fontSize=font;o.textStyle={bold:$('#dsbold').checked,italic:$('#dsitalic').checked,background:$('#dstextbackground').checked,border:$('#dstextborder').checked,align:$('#dstextalign').value,backgroundColor:$('#dstextbgcolor').value}}if(isFib(o)){const levels=$$('[data-ds-level]').map(row=>({enabled:row.querySelector('[data-level-prop="enabled"]').checked,value:+row.querySelector('[data-level-prop="value"]').value,color:row.querySelector('[data-level-prop="color"]').value,text:row.querySelector('[data-level-prop="text"]')?.value||'',opacity:Number(row.querySelector('[data-level-prop="opacity"]')?.value??100)/100,width:+row.querySelector('[data-level-prop="width"]').value,dash:row.querySelector('[data-level-prop="dash"]').value}));if(!levels.length||levels.length>30||levels.some(l=>!Number.isFinite(l.value)||Math.abs(l.value)>100||!Number.isFinite(l.opacity)||l.opacity<0||l.opacity>1))throw Error('Use 1–30 valid Fibonacci ratios between -100 and 100.');o.fib={...fibConfig(o),levels,showLevels:$('#dsfiblabels').checked,showPrices:$('#dsfibprices').checked,percent:$('#dsfibpercent').checked,reverse:$('#dsfibreverse').checked,background:$('#dsfibbackground').checked,trendLine:$('#dsfibtrend').checked,labelSide:$('#dsfibalign').value,labelVertical:$('#dsfibvertical')?.value||'top',showText:$('#dsfibtext')?.checked??true,textSide:$('#dsfibtextside')?.value||'center',textVertical:$('#dsfibtextvertical')?.value||'middle',logScale:$('#dsfiblog')?.checked??false,trendColor:$('#dsfibtrendcolor')?.value||s.color,trendWidth:Number($('#dsfibtrendwidth')?.value||1),trendDash:$('#dsfibtrenddash')?.value||'dashed'}}for(const el of $$('[data-anchor-price]')){const price=+el.value;if(!(price>0&&Number.isFinite(price)))throw Error('Anchor prices must be positive.');o[el.dataset.anchorPrice].p=price}for(const el of $$('[data-anchor-time]')){const key=el.dataset.anchorTime;if(el.value!==coordinateDate(base[key].t)){const time=Date.parse(el.value+'Z');if(!Number.isFinite(time))throw Error('Enter a valid date and time.');o[key].t=time}}if(o.type==='long'||o.type==='short'){const account=+$('#dsaccount').value,risk=+$('#dsrisk').value,lot=+$('#dslot').value;const mode=$('#dsriskmode').value,leverage=+$('#dsleverage').value;if(!(account>0&&risk>0&&(mode==='amount'||risk<=100)&&lot>0&&leverage>=1&&[account,risk,lot,leverage].every(Number.isFinite)))throw Error('Enter a positive account size, risk of 0–100%, and positive lot value.');o.risk={account,riskPercent:risk,riskMode:mode,lotSize:lot,leverage,precision:+$('#dsprecision').value};o.a.p=+$('#dsentryprice').value;if(!(o.a.p>0&&Number.isFinite(o.a.p)))throw Error('Entry price must be positive.');o.style.profitColor=$('#dsprofit').value;o.style.stopColor=$('#dsstopcolor').value;if($('#dspositionstop')){o.stop=+$('#dspositionstop').value;o.target=+$('#dspositiontarget').value;o.b.p=o.target}const sign=o.type==='long'?1:-1;if(!(o.stop>0&&o.target>0&&(o.a.p-o.stop)*sign>0&&(o.target-o.a.p)*sign>0))throw Error('Stop and target must remain on the correct sides of entry.')}return o}
function updatePositionPreview(o){const el=$('#dsriskpreview');if(!el||!o.risk)return;const amount=o.risk.riskMode==='amount'?o.risk.riskPercent:o.risk.account*o.risk.riskPercent/100,d=Math.abs(o.a.p-o.stop),qty=amount/(d*o.risk.lotSize),rr=Math.abs(o.target-o.a.p)/d;el.textContent=`Risk ${money(amount)} · Quantity ${qty.toFixed(o.risk.precision??3)} · Risk/Reward ${rr.toFixed(2)} · Margin ${money(o.a.p*qty*o.risk.lotSize/(o.risk.leverage||100))}`}
function applyDrawingForm(source,base){try{const next=readDrawingForm(base);if(source){checkpoint();Object.assign(source,next)}if(!source||$('#dssavedefaults').checked){toolDefaults[next.type]=drawingTemplateOptions(next);state.toolDefaults=toolDefaults}drawingEditDraft=null;settingsTarget=null;save();modal.innerHTML='';refreshDrawingBar();requestDraw()}catch(e){$('#dserror').textContent=e.message}}
drawingSettings=function(){openDrawingSettings(selected()||null)};
function closeDrawingContext(){$('#drawing-context')?.remove()}
function drawingContextMenu(x,y){closeDrawingContext();const o=selected();if(!o)return;const el=document.createElement('div');el.id='drawing-context';el.className='drawing-context';el.setAttribute('role','menu');el.style.left=Math.min(x,innerWidth-220)+'px';el.style.top=Math.min(y,innerHeight-330)+'px';el.innerHTML=[['drawsettings','Settings…'],['duplicatedrawing','Clone'],['lockdrawing',o.locked?'Unlock':'Lock'],['hidedrawing','Hide'],['drawingfront','Bring to front'],['drawingback','Send to back'],['deletedrawing','Remove']].map(([action,label])=>`<button role="menuitem" data-action="${action}">${label}</button>`).join('');document.body.append(el)}
const previousDrawingBarUnified=refreshDrawingBar;
refreshDrawingBar=function(){previousDrawingBarUnified();const o=selected(),bar=$('#drawingbar');if(!bar||!o)return;bar.innerHTML=`<span class="ds-object-name">${drawingNames[o.type]}</span><input type="color" id="drawingquickcolor" title="Color" aria-label="Drawing color" value="${drawingStyle(o).color}"><select id="drawingquickwidth" aria-label="Drawing line width">${[1,2,3,4,5,6].map(n=>`<option ${n===+drawingStyle(o).width?'selected':''}>${n}</option>`).join('')}</select>${button('⚙','drawsettings','small')}${button('⧉','duplicatedrawing','small')}${button(o.locked?'Unlock':'Lock','lockdrawing','small')}${button('⌫','deletedrawing','small')}${button('Fit','fitdrawing','small')}`;let quickColorChanged=false;$('#drawingquickcolor').oninput=e=>{if(!quickColorChanged){checkpoint();quickColorChanged=true}o.style={...drawingStyle(o),color:e.target.value};save();requestDraw()};$('#drawingquickcolor').onchange=()=>{quickColorChanged=false};$('#drawingquickwidth').onchange=e=>{checkpoint();o.style={...drawingStyle(o),width:+e.target.value};save();requestDraw()};};
Object.assign(actions,{drawsettings:()=>drawingSettings(),duplicatedrawing:()=>{const o=selected();if(!o)return;const g=geo[o.panel];checkpoint();const copy=g?translateDrawing(o,5,spec().pip*3,g):clone(o);copy.id=uid();copy.locked=false;chartObjects.push(copy);selectedDrawing=copy.id;save();refreshDrawingBar();requestDraw()},hidedrawing:()=>{const o=selected();if(!o)return;checkpoint();o.hidden=true;selectedDrawing=null;save();refreshDrawingBar();requestDraw()},drawingfront:()=>{const o=selected();if(!o)return;checkpoint();chartObjects=chartObjects.filter(x=>x.id!==o.id);chartObjects.push(o);save();requestDraw()},drawingback:()=>{const o=selected();if(!o)return;checkpoint();chartObjects=chartObjects.filter(x=>x.id!==o.id);chartObjects.unshift(o);save();requestDraw()}});
const dismissBeforeDrawingSystem=actions.dismiss;actions.dismiss=()=>{drawingEditDraft=null;settingsTarget=null;dismissBeforeDrawingSystem();requestDraw()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!e.target.closest('#drawing-context'))closeDrawingContext();else if(b?.dataset.action)closeDrawingContext();if(!b)return;const d=b.dataset;if(d.selectObject||d.settingsObject){tool='crosshair';pending=null;drawingGesture=null;syncToolButtons();requestDraw()}if(d.dsTab){$$('[data-ds-tab]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-selected',x===b)});$$('[data-ds-section]').forEach(x=>x.classList.toggle('hide',x.dataset.dsSection!==d.dsTab))}if(b.hasAttribute('data-ds-allframes')){$$('[id^="dsframe"]').forEach(el=>el.checked=true);$('#dsform').dispatchEvent(new Event('input',{bubbles:true}))}if(b.hasAttribute('data-ds-add-level')){const levels=readEditorLevels();if(levels.length>=30)return toast('Maximum 30 Fibonacci levels.');levels.push({enabled:true,value:1.618,color:'#78a6ff',width:2,dash:'solid'});$('#dslevels').innerHTML=levelEditorRows(levels);$('#dsform').dispatchEvent(new Event('input',{bubbles:true}))}if(d.dsRemoveLevel!==undefined){b.closest('[data-ds-level]').remove();$('#dslevels').innerHTML=levelEditorRows(readEditorLevels());$('#dsform').dispatchEvent(new Event('input',{bubbles:true}))}if(b.hasAttribute('data-ds-save-template')){try{const source=chartObjects.find(o=>o.id===settingsTarget),base=drawingEditDraft||source||defaultDrawing(settingsType,activePanel,[{t:current().t,p:current().c},{t:current().t+60000,p:current().c+spec().pip*10},{t:current().t+120000,p:current().c+spec().pip*5}].slice(0,DRAWING_TOOLS[settingsType].points)),value=readDrawingForm(base),name=$('#dstemplatename').value.trim();if(!name)return toast('Enter a template name.');state.drawingTemplates??=[];const template={id:uid(),type:settingsType,name,options:drawingTemplateOptions(value)};state.drawingTemplates.push(template);save();const option=document.createElement('option');option.value=template.id;option.textContent=name;$('#dstemplate').append(option);toast('Template saved.')}catch(err){$('#dserror').textContent=err.message}}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawingContext();drawingEditDraft=null;settingsTarget=null;cancelDrawingGesture()}if(!active||modal.innerHTML||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&selected()){e.preventDefault();actions.duplicatedrawing()}});

function readEditorLevels(){return $$('[data-ds-level]').map(row=>({enabled:row.querySelector('[data-level-prop="enabled"]').checked,value:+row.querySelector('[data-level-prop="value"]').value,color:row.querySelector('[data-level-prop="color"]').value,text:row.querySelector('[data-level-prop="text"]')?.value||'',opacity:Number(row.querySelector('[data-level-prop="opacity"]')?.value??100)/100,width:+row.querySelector('[data-level-prop="width"]').value,dash:row.querySelector('[data-level-prop="dash"]').value}))}
actions.fitdrawing=()=>{const o=selected();if(!o)return;const prices=objectPoints(o).map(x=>x.point.p);if(o.target!==undefined)prices.push(o.target,o.stop);if(isFib(o))prices.push(...fibConfig(o).levels.filter(l=>l.enabled!==false).map(l=>fibPrice(o,l.value)));const lo=Math.min(...prices),hi=Math.max(...prices),pad=Math.max(spec().pip*5,(hi-lo)*.12);panelViews[o.panel]={manual:true,lo:lo-pad,hi:hi+pad};activePanel=o.panel;refreshViewControls();requestDraw()};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&(pending||drawingGesture)&&!modal.innerHTML){e.preventDefault();e.stopImmediatePropagation();cancelDrawingGesture()}},true);

// Cancel drafts before replacing the time/price geometry or chart elements.
document.addEventListener('click',e=>{if((pending||drawingGesture)&&e.target.closest('[data-interval],[data-maximize],[data-action="resetview"],[data-action="back"]'))cancelDrawingGesture()},true);
document.addEventListener('change',e=>{if((pending||drawingGesture)&&e.target.matches('[data-frame],#chartlayout,#workspace-type'))cancelDrawingGesture()},true);

// Shared price geometry is used for paint, selection and fit-to-levels.
function fibLabelPosition(bounds,side,vertical,y,size){return {x:side==='left'?bounds.left+5:side==='center'?(bounds.left+bounds.right)/2:bounds.right-5,y:y+(vertical==='bottom'?size+2:vertical==='middle'?size*.35:-5),align:side==='left'?'left':side==='center'?'center':'right'}}
function paintFibDrawing(ctx,o,g,s,draft=false){
  const cfg=fibConfig(o),bounds=fibRange(o,g),levels=cfg.levels.filter(l=>l.enabled!==false).map(l=>({...l,price:fibPrice(o,+l.value)})).filter(l=>Number.isFinite(l.price)).sort((x,y)=>x.price-y.price),alpha=(s.opacity??1)*(draft?.75:1),size=s.labelSize||11;
  if(cfg.background)for(let i=0;i<levels.length-1;i++){ctx.save();ctx.fillStyle=levels[i].color||s.color;ctx.globalAlpha=alpha*Number(s.fill)*(levels[i].opacity??1);const y1=g.py(levels[i].price),y2=g.py(levels[i+1].price);ctx.fillRect(bounds.left,y1,bounds.right-bounds.left,y2-y1);ctx.restore()}
  for(const l of levels){ctx.save();ctx.globalAlpha=alpha*(l.opacity??1);setCanvasStyle(ctx,{...s,color:l.color||s.color,width:l.width||s.width,dash:l.dash||s.dash});const y=g.py(l.price);strokeSegment(ctx,[{x:bounds.left,y},{x:bounds.right,y}]);let label=cfg.showLevels?(cfg.percent?Number((Number(l.value)*100).toFixed(6))+'%':String(l.value)):'';if(cfg.showPrices)label+=(label?' (':'')+l.price.toFixed(spec().dec)+(label?')':'');ctx.fillStyle=l.color||s.color;ctx.font=`${size}px Arial`;if(label){const p=fibLabelPosition(bounds,cfg.labelSide,cfg.labelVertical,y,size);ctx.textAlign=p.align;ctx.fillText(label,p.x,p.y)}if(cfg.showText!==false&&l.text){const p=fibLabelPosition(bounds,cfg.textSide||'center',cfg.textVertical||'middle',y,size);ctx.textAlign=p.align;ctx.fillText(String(l.text),p.x,p.y)}ctx.restore()}
  if(cfg.trendLine){setCanvasStyle(ctx,{...s,color:cfg.trendColor||s.color,width:cfg.trendWidth||1,dash:cfg.trendDash||'dashed'});const pts=pixelPoints(o,g);pts.slice(1).forEach((p,i)=>strokeSegment(ctx,[pts[i],p]))}
}
